    def smallestNumber(self, num: int) -> int:
        if num == 0:
            return 0
        negative = num < 0
        s = str(abs(num))
        digits = list(s)
        if negative:
            digits.sort(reverse=True)  # descending for negative
            return int('-' + ''.join(digits))
        else:
            digits.sort()  # ascending
